Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'wait-for.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Print every match of a pattern in a log file, once it is there: surl writes an exchange's`n# last lines a moment after its client has gone, so wait, at most 10 s, for the first match.`n# Usage: sh wait-for.sh <log file> <pattern>`ni=0`nuntil grep -q `"`$2`" `"`$1`"; do`n  i=`$((i+1)); [ `$i -ge 100 ] && break; sleep 0.1`ndone`ngrep -o `"`$2`" `"`$1`"`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', 'nats://127.0.0.1:8083/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -u tok123: -d paid nats://127.0.0.1:8083/orders.new } finally { Stop-Process $server0 }
